using System.Collections.Generic; using System.Linq; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class CartController:Controller { private StoreContext db=new StoreContext(); private List<CartItem> Cart {get {if(Session["Cart"]==null)Session["Cart"]=new List<CartItem>();return (List<CartItem>)Session["Cart"];}} public ActionResult Index(){return View(Cart);} public ActionResult Add(int id){var p=db.Products.Find(id);if(p!=null){var item=Cart.FirstOrDefault(x=>x.ProductID==id);if(item==null)Cart.Add(new CartItem{ProductID=p.ProductID,ProductName=p.ProductName,ProductImage=p.ProductImage,UnitPrice=p.ProductPrice,Quantity=1});else item.Quantity++;}return RedirectToAction("Index");} [HttpPost] public ActionResult Update(int id,int quantity){var item=Cart.FirstOrDefault(x=>x.ProductID==id);if(item!=null){if(quantity<=0)Cart.Remove(item);else item.Quantity=quantity;}return RedirectToAction("Index");} public ActionResult Remove(int id){var item=Cart.FirstOrDefault(x=>x.ProductID==id);if(item!=null)Cart.Remove(item);return RedirectToAction("Index");} } }